  ($q$safeguardingContact$q$, $q$Officer Jones, our Child Safety Officer$q$, 'published', true, $q$Seeded from the website's bundled value (src/config/legal.ts, docs/LEGAL_FACT_KEYS.json, 2026-10-05). Confirmed by the owner on 2026-10-05.$q$, now(), 'system:seed', (current_date + interval '12 months')::date),
