  ($q$coachOsUrl$q$, $q$https://app.risingstars.training$q$, 'published', false, $q$Managed in the website's code.$q$, now(), 'system:seed', NULL),
  ($q$governingLaw$q$, $q$the State of Texas$q$, 'published', false, $q$Managed in the website's code.$q$, now(), 'system:seed', NULL),
  ($q$venue$q$, $q$the county in Texas where the program took place (Dallas, Tarrant, Collin or Denton County)$q$, 'published', true, $q$Seeded from the website's bundled value (src/config/legal.ts, docs/LEGAL_FACT_KEYS.json, 2026-10-05). Confirmed by the owner on 2026-10-05.$q$, now(), 'system:seed', (current_date + interval '12 months')::date),
  ($q$ageRange$q$, $q$4–12$q$, 'published', false, $q$Managed in the website's code.$q$, now(), 'system:seed', NULL),
  ($q$paymentProcessor$q$, $q$Stripe$q$, 'published', false, $q$Managed in the website's code.$q$, now(), 'system:seed', NULL),
  ($q$billingCycle$q$, $q$We invoice monthly through CoachOS at the start of each month your child is enrolled.$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$refundWindow$q$, $q$All payments are final and non-refundable. In special circumstances (for example a serious injury or illness that keeps your child from taking part, or a family relocation) you may ask for an exception; any refund or credit is at Rising Stars’ discretion.$q$, 'published', true, $q$Seeded from the website's bundled value (src/config/legal.ts, docs/LEGAL_FACT_KEYS.json, 2026-10-05). Confirmed by the owner on 2026-10-05.$q$, now(), 'system:seed', (current_date + interval '12 months')::date),
  ($q$cancellationNotice$q$, $q$Tell us before the 1st of the next month to stop future monthly charges. The current month is not refunded.$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$makeUpPolicy$q$, $q$We offer a make-up session; if a make-up isn’t possible, we give a credit toward a future month.$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$missedSessionPolicy$q$, $q$They are not refunded, credited or made up.$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$lateFee$q$, $q$none. If an invoice is more than 14 days overdue, your child’s spot may be released to the waitlist.$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$latePickupPolicy$q$, $q$Please pick up on time. A coach always stays with your child. After 15 minutes we call you and then your emergency contacts; repeated late pick-ups may lead to removal from the program. There is no late pick-up fee.$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$heatPolicy$q$, $q$We check the heat index before every outdoor session. At 90°F or above we add water and shade breaks at least every 15 minutes; at 100°F or above we shorten the session and lower its intensity; at 105°F or above, or during lightning, we move indoors or cancel$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$youthCampLicense$q$, $q$We do not hold a youth camp license and do not run youth camps. Our programs meet fewer than four consecutive days, so they are not youth camps under ch. 141. Before we ever offer a program that meets four or more consecutive days, we will obtain a DSHS youth camp license first.$q$, 'published', true, $q$Seeded from the website's bundled value (src/config/legal.ts, docs/LEGAL_FACT_KEYS.json, 2026-10-05). Confirmed by the owner on 2026-10-05.$q$, now(), 'system:seed', (current_date + interval '12 months')::date),
  ($q$insurance$q$, $q$Rising Stars Youth Academy is insured. Details of our coverage are available to host schools and families on request.$q$, 'published', true, $q$Seeded from the website's bundled value (src/config/legal.ts, docs/LEGAL_FACT_KEYS.json, 2026-10-05). Confirmed by the owner on 2026-10-05.$q$, now(), 'system:seed', (current_date + interval '12 months')::date),
  ($q$backgroundCheckProvider$q$, $q$the screening required by each host school district or charter school, plus a national criminal background check renewed every 2 years$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$safeguardingTraining$q$, $q$an abuse-prevention and mandatory-reporting course (such as Darkness to Light’s Stewards of Children) completed before working with children and renewed every 2 years$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$firstAidCertification$q$, $q$Every coach holds current CPR, AED and first aid certification from the American Red Cross or the American Heart Association.$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$ngbAffiliation$q$, $q$Rising Stars is not a member of any national governing body and does not take part in interstate or international competition, so the Act does not apply to us$q$, 'published', true, $q$Seeded from the website's bundled value (src/config/legal.ts, docs/LEGAL_FACT_KEYS.json, 2026-10-05). Confirmed by the owner on 2026-10-05.$q$, now(), 'system:seed', (current_date + interval '12 months')::date),
  ($q$medicationPolicy$q$, $q$Staff do not give routine medication. Children may carry and use their own asthma inhalers and epinephrine auto-injectors, and staff trained to do so may help in an emergency. Tell us about these in the registration form.$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$aedAvailability$q$, $q$Texas public school campuses must keep an AED on site (Tex. Educ. Code §38.017); coaches learn where it is before the first session. At other venues coaches identify the nearest AED in advance and call 911 first in any emergency.$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$conductRefund$q$, $q$No refund or credit is given, consistent with our no-refund policy.$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$photoDeviceStorage$q$, $q$Photos are taken on Rising Stars devices or uploaded to the CoachOS photo library the same day and deleted from personal phones.$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$gaMeasurementId$q$, $q$G-38R9243PKK$q$, 'published', false, $q$Managed in the website's code.$q$, now(), 'system:seed', NULL),
  ($q$smsProvider$q$, $q$Rising Stars staff (sent directly from our business phone; we do not use a third-party texting service)$q$, 'published', true, $q$Seeded from the website's bundled value (src/config/legal.ts, docs/LEGAL_FACT_KEYS.json, 2026-10-05). Confirmed by the owner on 2026-10-05.$q$, now(), 'system:seed', (current_date + interval '12 months')::date),
  ($q$retention.registration$q$, $q$while your child is enrolled and 3 years after the last program they attended$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$retention.medical$q$, $q$deleted 12 months after the child’s last active enrollment, unless an incident report requires longer$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$retention.incidentReports$q$, $q$until the child turns 21 (Texas’ two-year limitations period runs from age 18, plus one year of margin)$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$retention.payments$q$, $q$7 years, for tax and accounting records (names and contact details are removed if you ask us to delete your data)$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$retention.inquiries$q$, $q$24 months after we receive them$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$retention.privacyRequests$q$, $q$36 months after the request is closed (the record of the request and our response)$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$retention.analytics$q$, $q$14 months (Google Analytics data retention setting)$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date),
  ($q$retention.errorLogs$q$, $q$up to 90 days (Sentry), with personal details removed before they are sent$q$, 'published', false, $q$Seeded from the website's bundled value (src/config/legal.ts, 2026-10-05). A default chosen by the website team, not yet checked: research it, correct it if needed, and send it for review.$q$, now(), 'system:seed', current_date)
  ) AS v(key, value, status, verified, notes, published_at, reviewed_by, review_due)
