INSERT INTO ops.legal_document_versions (document, version, effective_date, fact_keys, published_by)
SELECT d, '2026-10-05', DATE '2026-10-05', '{}', 'system:seed'
  FROM unnest(ARRAY['privacy', 'terms', 'registration_terms', 'child_safety', 'accessibility', 'privacy_choices']) AS d
ON CONFLICT (document, version) DO NOTHING;
